// Rentan Carousel
let carouselData = [];
let carouselCurrentIndex = 0;
let carouselInterval = null;
let carouselPaused = false;
let carouselMode = 'current'; // 'current' or 'compiled'
let currentContextData = null;
let compiledContextData = null;

function formatCarouselItems(data) {
    const items = [];

    // Time with timezone and analog clock icon (always show if time exists)
    if (data.time) {
        // Compute analog clock icon on client
        const hour = data.time.hour;
        const minute = data.time.minute;

        // Format time if not already formatted (handle both formatted and raw time objects)
        let formattedTime = data.time.formatted;
        if (!formattedTime && hour !== undefined && minute !== undefined) {
            formattedTime = `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
        }

        if (formattedTime) {
            const analogIcon = getAnalogClockIcon(hour, minute);

            // Compute timezone info on client
            const timezone = data.time.timezone;
            const timezoneInfo = timezone ? formatTimezoneInfo(timezone) : null;

            let timeText = timezoneInfo && timezoneInfo.offset !== 0
                ? `${formattedTime} <span class="timezone-dimmed">${timezoneInfo.formatted}</span>`
                : formattedTime;

            // Add holiday and date next to time - only for compiled context or if explicitly set
            // Check if we're in compiled mode or if date was explicitly set in request
            const isCompiledContext = carouselMode === 'compiled';
            const hasExplicitDate = data.date?.formatted !== undefined;
            // Holiday is always at data.season?.holiday (consistent structure for both live and compiled)
            const holiday = data.season?.holiday;
            const hasHoliday = holiday?.primaryHoliday?.name !== undefined;

            // Add holiday between time and date if available
            if (hasHoliday) {
                const holidayName = holiday.primaryHoliday.name;
                const daysUntil = holiday.primaryHoliday.daysUntil ?? holiday.progressiveElements?.daysUntil;
                const daysText = daysUntil !== undefined && daysUntil !== null ? ` (in ${daysUntil} day${daysUntil !== 1 ? 's' : ''})` : '';
                timeText += ` <span class="carousel-separator">•</span> <i class="fa-solid fa-gifts carousel-inline-icon"></i> ${holidayName}${daysText}`;
            }

            if ((isCompiledContext || hasExplicitDate) && data.time.monthName && data.time.dayOfMonth !== undefined) {
                // Format date as short month name and day number (e.g., "Nov 14")
                const shortMonthName = data.time.monthName.substring(0, 3);
                const dateText = `${shortMonthName} ${data.time.dayOfMonth}`;
                timeText += ` <span class="carousel-separator">•</span> ${dateText}`;
            } else if ((isCompiledContext || hasExplicitDate) && data.time.month !== undefined && data.time.dayOfMonth !== undefined) {
                // Fallback: use month number if monthName is not available
                const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
                const monthIndex = typeof data.time.month === 'number' ? data.time.month - 1 : parseInt(data.time.month) - 1;
                if (monthIndex >= 0 && monthIndex < 12) {
                    const dateText = `${monthNames[monthIndex]} ${data.time.dayOfMonth}`;
                    timeText += ` <span class="carousel-separator">•</span> ${dateText}`;
                }
            }

            items.push({
                icon: 'fa-solid ' + analogIcon,
                text: timeText
            });
        }
    }

    // Combine Time of Day and Season into one item
    // Handle both timeOfDay (from current context) and timePeriod (from compiled context)
    let timeOfDayData = null;
    let timePeriodData = null;

    /**
     * Normalizes legacy period keys to new period key names (client-side)
     */
    function normalizePeriodKey(periodKey) {
        if (!periodKey || typeof periodKey !== 'string') {
            return periodKey;
        }

        const normalized = periodKey.toLowerCase().trim();

        const legacyMappings = {
            'earlymorning': 'morning',
            'early_morning': 'morning',
            'earlyevening': 'evening', // Keep as evening, not night
            'early_evening': 'evening',
            // 'evening' is now a valid period name (used for cloudy afternoon golden hour), don't map to 'night'
            'lateevening': 'night',
            'late_evening': 'night'
        };

        return legacyMappings[normalized] || normalized;
    }

    // Helper function to extract periodKey from period string
    function extractPeriodKeyFromPeriod(periodStr) {
        if (!periodStr) return null;
        const period = periodStr.toLowerCase();

        // Try to match period string to periodKey
        if (period.includes('late morning') || period.includes('late-morning')) {
            return 'latemorning';
        } else if (period.includes('early afternoon') || period.includes('early-afternoon')) {
            return 'earlyafternoon';
        } else if (period.includes('late afternoon') || period.includes('late-afternoon')) {
            return 'lateafternoon';
        } else if (period.includes('late night') || period.includes('late-night')) {
            return 'latenight';
        } else if (period.includes('golden hour') || period.includes('golden-hour')) {
            return 'goldenhour';
        } else if (period.includes('pre-dawn') || period.includes('predawn')) {
            return 'predawn';
        } else {
            // Try to extract the main word (morning, afternoon, evening, night, etc.)
            // Note: 'evening' is now a valid period name (used for cloudy afternoon golden hour)
            const mainWords = ['dawn', 'sunrise', 'morning', 'noon', 'daytime', 'afternoon', 'evening', 'sunset', 'dusk', 'twilight', 'night', 'midnight'];
            for (const word of mainWords) {
                if (period.includes(word)) {
                    return word;
                }
            }
        }
        return null;
    }

    // Check for timeOfDay structure (from current context)
    if (data.timeOfDay && data.timeOfDay.name) {
        // timeOfDay exists and has a valid name - use it
        timeOfDayData = data.timeOfDay;
    }
    // Check for timePeriod structure (from compiled context)
    // Process timePeriod if timeOfDay doesn't exist or doesn't have a valid name
    else if (data.timePeriod) {
        timePeriodData = data.timePeriod;
        // Convert timePeriod to timeOfDay-like structure
        if (typeof timePeriodData === 'object' && timePeriodData !== null) {
            // Extract periodKey or infer from period
            let periodKey = timePeriodData.periodKey;

            // If periodKey is missing but period exists, try to extract periodKey from period
            if (!periodKey && timePeriodData.period) {
                periodKey = extractPeriodKeyFromPeriod(timePeriodData.period);
            }

            // Normalize legacy period keys
            if (periodKey) {
                periodKey = normalizePeriodKey(periodKey);
            }

            timeOfDayData = {
                name: periodKey || timePeriodData.period || null,
                description: timePeriodData.period || null
            };
        } else if (typeof timePeriodData === 'string') {
            // If timePeriod is a string, use it directly
            const extractedKey = extractPeriodKeyFromPeriod(timePeriodData);
            const normalizedKey = normalizePeriodKey(extractedKey || timePeriodData);
            timeOfDayData = {
                name: normalizedKey,
                description: timePeriodData
            };
        }
    }
    // If timeOfDay exists but name is null, try to extract from description
    else if (data.timeOfDay && data.timeOfDay.description) {
        const extractedKey = extractPeriodKeyFromPeriod(data.timeOfDay.description);
        if (extractedKey) {
            timeOfDayData = {
                name: extractedKey,
                description: data.timeOfDay.description
            };
        }
    }

    if (timeOfDayData || data.season) {
        let timeIcon = '';
        let timeText = '';
        let seasonIcon = '';
        let seasonText = '';

        // Time of day - handle timeOfDayData structure
        if (timeOfDayData && timeOfDayData.name) {
            const periodName = timeOfDayData.name;

            if (periodName) {
                // Determine icon based on time period
                let todIcon = 'fa-regular fa-sun';
                const timePeriod = periodName.toLowerCase();

                if (timePeriod.includes('dawn') || timePeriod.includes('sunrise')) {
                    todIcon = 'fa-regular fa-sunrise';
                } else if (timePeriod.includes('morning')) {
                    todIcon = 'fa-regular fa-coffee-pot';
                } else if (timePeriod.includes('daytime')) {
                    todIcon = 'fa-regular fa-sun';
                } else if (timePeriod.includes('afternoon')) {
                    todIcon = 'fa-regular fa-mug-tea-saucer';
                } else if (timePeriod.includes('evening')) {
                    todIcon = 'fa-regular fa-sun-haze';
                } else if (timePeriod.includes('dusk') || timePeriod.includes('sunset')) {
                    todIcon = 'fa-regular fa-sunset';
                } else if (timePeriod.includes('night') || timePeriod.includes('midnight')) {
                    todIcon = 'fa-regular fa-moon';
                }

                // Use the same periodKey mapping as the compiled prompt modal
                let periodDisplayName = 'Time';
                const periodKeyMap = {
                    'predawn': 'Pre-Dawn',
                    'pre_dawn': 'Pre-Dawn',
                    'dawn': 'Dawn',
                    'sunrise': 'Sunrise',
                    'morning': 'Morning',
                    'latemorning': 'Late Morning',
                    'late_morning': 'Late Morning',
                    'noon': 'Noon',
                    'daytime': 'Daytime',
                    'earlyafternoon': 'Early Afternoon',
                    'early_afternoon': 'Early Afternoon',
                    'afternoon': 'Afternoon',
                    'lateafternoon': 'Late Afternoon',
                    'late_afternoon': 'Late Afternoon',
                    'goldenhour': 'Golden Hour',
                    'golden_hour': 'Golden Hour',
                    'evening': 'Evening',
                    'sunset': 'Sunset',
                    'dusk': 'Dusk',
                    'twilight': 'Twilight',
                    'night': 'Night',
                    'midnight': 'Midnight',
                    'latenight': 'Late Night',
                    'late_night': 'Late Night'
                };

                periodDisplayName = periodKeyMap[periodName.toLowerCase()] ||
                    periodName
                        .split('_')
                        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
                        .join(' ');

                timeIcon = todIcon;
                timeText = periodDisplayName;
            }
        }

        // Season - handle both object and string formats (for backward compatibility with compiled prompts)
        if (data.season) {
            let seasonIconClass = 'fas fa-leaf-maple'; // default
            // Extract season name from object or use string directly
            let seasonName;
            if (typeof data.season === 'object' && data.season !== null && data.season.name) {
                seasonName = data.season.name;
            } else if (typeof data.season === 'string') {
                seasonName = data.season;
            } else {
                // Fallback: try to convert to string
                seasonName = String(data.season);
            }
            const season = seasonName.toLowerCase();

            if (season.includes('spring')) {
                seasonIconClass = 'fas fa-flower-tulip';
            } else if (season.includes('summer')) {
                seasonIconClass = 'fas fa-hat-beach';
            } else if (season.includes('autumn') || season.includes('fall')) {
                seasonIconClass = 'fas fa-leaf';
            } else if (season.includes('winter')) {
                seasonIconClass = 'fas fa-snowflake';
            }

            seasonIcon = seasonIconClass;
            seasonText = seasonName.charAt(0).toUpperCase() + seasonName.slice(1);
        }

        // Build text with icons inline - period icon with period text, season icon with season text
        let displayText = '';
        let displayIcon = '';

        if (timeText && seasonText) {
            // Both exist - period icon at start, season icon after separator
            displayText = `<i class="${timeIcon} carousel-inline-icon"></i> ${timeText} <span class="carousel-separator">•</span> <i class="${seasonIcon} carousel-inline-icon"></i> ${seasonText}`;
            displayIcon = ''; // No icon container needed, icons are in text
        } else if (timeText) {
            // Only period
            displayText = `<i class="${timeIcon} carousel-inline-icon"></i> ${timeText}`;
            displayIcon = ''; // No icon container needed
        } else if (seasonText) {
            // Only season
            displayText = `<i class="${seasonIcon} carousel-inline-icon"></i> ${seasonText}`;
            displayIcon = ''; // No icon container needed
        }

        items.push({
            icon: displayIcon,
            text: displayText,
            hasTime: !!timeText,
            hasSeason: !!seasonText,
            timeIcon: timeIcon,
            seasonIcon: seasonIcon,
            inlineIcons: true // Flag to indicate icons are in text
        });
    }


    // Date - only shown if overridden (handled server-side)
    if (data.date?.formatted) {
        items.push({
            icon: 'fa-regular fa-calendar',
            text: data.date.formatted
        });
    }

    // Weather with condition-specific icon
    if (data.weather) {
        // Use feelsLike temperature with proper unit conversion
        const tempData = formatTemperature(data.weather.feelsLike);
        const weatherText = `${tempData.number}<span class="weather-unit">${tempData.unit}</span> <span class="weather-condition">${data.weather.condition}</span>`;

        // Determine if it's night based on timePeriod data
        const isNight = data.timePeriod?.isDaytime === false;
        const timePrefix = isNight ? 'night-alt' : 'day';

        let weatherIcon = isNight ? 'wi wi-night-clear' : 'wi wi-day-sunny'; // default

        if (data.weather.condition) {
            const conditionLower = data.weather.condition.toLowerCase();

            // Icons that don't change between day/night
            const timeNeutralIcons = {
                'overcast': 'wi wi-cloudy',
                'fog': 'wi wi-fog',
                'depositing rime fog': 'wi wi-fog',
                'moderate snow fall': 'wi wi-snow',
                'heavy snow fall': 'wi wi-snow',
                'snow grains': 'wi wi-snow',
                'heavy snow showers': 'wi wi-snow'
            };

            if (timeNeutralIcons[conditionLower]) {
                weatherIcon = timeNeutralIcons[conditionLower];
            } else {
                // Time-dependent icons
                const iconMap = {
                    'clear sky': isNight ? 'wi wi-night-clear' : 'wi wi-day-sunny',
                    'mainly clear': isNight ? 'wi wi-night-alt-partly-cloudy' : 'wi wi-day-sunny-overcast',
                    'partly cloudy': `wi wi-${timePrefix}-cloudy`,
                    'light drizzle': `wi wi-${timePrefix}-showers`,
                    'moderate drizzle': `wi wi-${timePrefix}-showers`,
                    'dense drizzle': `wi wi-${timePrefix}-showers`,
                    'light freezing drizzle': `wi wi-${timePrefix}-snow`,
                    'dense freezing drizzle': `wi wi-${timePrefix}-snow`,
                    'slight rain': `wi wi-${timePrefix}-rain`,
                    'moderate rain': `wi wi-${timePrefix}-rain`,
                    'heavy rain': `wi wi-${timePrefix}-rain`,
                    'light freezing rain': `wi wi-${timePrefix}-snow`,
                    'heavy freezing rain': `wi wi-${timePrefix}-snow`,
                    'slight snow fall': `wi wi-${timePrefix}-snow`,
                    'slight rain showers': `wi wi-${timePrefix}-showers`,
                    'moderate rain showers': `wi wi-${timePrefix}-rain`,
                    'violent rain showers': `wi wi-${timePrefix}-storm-showers`,
                    'slight snow showers': `wi wi-${timePrefix}-snow`,
                    'thunderstorm': `wi wi-${timePrefix}-thunderstorm`,
                    'thunderstorm with slight hail': `wi wi-${timePrefix}-thunderstorm`,
                    'thunderstorm with heavy hail': `wi wi-${timePrefix}-thunderstorm`
                };

                weatherIcon = iconMap[conditionLower] || (isNight ? 'wi wi-night-clear' : 'wi wi-day-sunny');
            }
        }

        items.push({
            icon: weatherIcon,
            text: weatherText
        });
    }

    // Location (if available and static - not auto-detected from IP)
    if (data.location && (data.location.city || data.location.country)) {
        // Check if location was manually set (static) or auto-detected from IP
        // Static locations have source: 'static'
        // Auto-detected locations have source: 'ipinfo', 'ipapi', or 'fallback'
        const isStaticLocation = data.location.source === 'static';

        if (isStaticLocation) {
            const locationText = [data.location.city, data.location.country].filter(Boolean).join(', ');
            items.push({
                icon: 'fa-solid fa-location-dot',
                text: locationText
            });
        }
    }

    return items;
}

function updateDynamicCarousel(data, mode = null) {
    if (!data) return;
    if (!dynamicCarousel) return;

    // Store data based on mode
    if (mode === 'compiled') {
        compiledContextData = data;
        // Update mode if explicitly set to compiled
        carouselMode = 'compiled';
    } else if (mode === 'current') {
        currentContextData = data;
        // Update mode if explicitly set to current
        carouselMode = 'current';
    } else {
        // No mode specified, store as current context
        currentContextData = data;
    }

    // Use specified mode or current mode
    const targetMode = mode || carouselMode;

    // Determine which data to display
    let displayData = targetMode === 'compiled' ? compiledContextData : currentContextData;

    // If target mode is compiled but no compiled data, use current data
    if (targetMode === 'compiled' && !displayData) {
        displayData = currentContextData;
    }

    if (!displayData) return;

    carouselData = formatCarouselItems(displayData);

    if (carouselData.length === 0) {
        carouselData = [{
            icon: 'fa-regular fa-circle-info',
            text: 'Select Options...'
        }];
    }

    // Clear existing carousel items (but preserve indicators)
    const indicators = dynamicCarousel.querySelector('.carousel-indicators');
    dynamicCarousel.innerHTML = '';
    if (indicators) {
        dynamicCarousel.appendChild(indicators);
    }

    // Create all carousel items in the DOM (stacked)
    carouselData.forEach((item, index) => {
        const carouselItem = document.createElement('div');
        carouselItem.className = 'carousel-item';
        if (index === 0) {
            carouselItem.classList.add('active');
        }
        carouselItem.dataset.index = index;

        // If icons are inline in the text, don't create icon container
        if (item.inlineIcons) {
            // Icons are already in the text, just render the text
            const textEl = document.createElement('span');
            textEl.className = 'carousel-text';
            textEl.innerHTML = item.text;
            carouselItem.appendChild(textEl);
        } else {
            // Handle icon container for items with separate icons
            const iconContainer = document.createElement('div');
            iconContainer.className = 'carousel-icon-container';

            if (item.icon && item.icon.includes('|')) {
                // Multiple icons
                const icons = item.icon.split('|');
                icons.forEach(icon => {
                    if (icon.trim()) {
                        const iconEl = document.createElement('i');
                        iconEl.className = `carousel-icon ${icon.trim()}`;
                        iconContainer.appendChild(iconEl);
                    }
                });
            } else if (item.icon) {
                // Single icon
                const iconEl = document.createElement('i');
                iconEl.className = `carousel-icon ${item.icon}`;
                iconContainer.appendChild(iconEl);
            }

            const textEl = document.createElement('span');
            textEl.className = 'carousel-text';
            textEl.innerHTML = item.text;

            carouselItem.appendChild(iconContainer);
            carouselItem.appendChild(textEl);
        }

        dynamicCarousel.insertBefore(carouselItem, indicators || null);
    });

    carouselCurrentIndex = 0;
    updateCarouselIndicators();
    startCarousel();
}

function showCarouselItem(index) {
    if (!dynamicCarousel || carouselData.length === 0) return;

    // Remove active class from all items
    const allItems = dynamicCarousel.querySelectorAll('.carousel-item');
    allItems.forEach(item => {
        item.classList.remove('active');
    });

    // Add active class to current item - CSS handles the animation
    const currentItem = dynamicCarousel.querySelector(`.carousel-item[data-index="${index}"]`);
    if (currentItem) {
        currentItem.classList.add('active');
    }
}

function advanceCarousel() {
    if (carouselPaused || carouselData.length <= 1) return;

    // Move to next index
    carouselCurrentIndex = (carouselCurrentIndex + 1) % carouselData.length;

    // Update active item - CSS handles the animation
    showCarouselItem(carouselCurrentIndex);

    // Update indicators including cache expiration status
    updateCarouselIndicators();
}

function startCarousel() {
    stopCarousel();

    if (carouselData.length > 1) {
        carouselInterval = setInterval(advanceCarousel, 4000);
    }
}

function stopCarousel() {
    if (carouselInterval) {
        clearInterval(carouselInterval);
        carouselInterval = null;
    }
}

function pauseCarousel() {
    carouselPaused = true;
}

function resumeCarousel() {
    carouselPaused = false;
}

function updateCarouselIndicators() {
    const indicators = document.getElementById('carouselIndicators');
    const currentIndicator = document.getElementById('currentContextIndicator');
    const compiledIndicator = document.getElementById('compiledContextIndicator');
    const lockIcon = document.getElementById('carouselLockIcon');
    const fastIcon = document.getElementById('carouselFastIcon');
    const cacheIcon = document.getElementById('carouselCacheIcon');

    if (!dynamicCarousel || !indicators || !currentIndicator || !compiledIndicator) return;

    // Show indicators only if compiled prompt context exists
    // Check both window.dynamicGenerationData and compiledContextData
    const hasCompiledPrompt = window.dynamicGenerationData?.compiled_prompt?.context || compiledContextData;

    if (hasCompiledPrompt) {
        indicators.classList.remove('hidden');
        dynamicCarousel.classList.add('has-indicators');

        // Show/hide lock icon based on freeze state
        // Priority: Freeze Changes (lock icon) > Freeze Context (icicles icon)
        if (lockIcon && dynamicCarousel) {
            const { cacheLocked: isChangesLocked, contextLocked: isContextLocked } = getDynamicGenerationLockState();

            if (isChangesLocked) {
                // Freeze Changes takes priority - show lock icon
                lockIcon.classList.remove('hidden');
                lockIcon.className = 'carousel-lock-icon fa-solid fa-lock';
                lockIcon.title = 'Changes Frozen';
            } else if (isContextLocked) {
                // Freeze Context - show icicles icon
                lockIcon.classList.remove('hidden');
                lockIcon.className = 'carousel-lock-icon fa-solid fa-icicles';
                lockIcon.title = 'Context Frozen';
            } else {
                // Neither is locked - hide icon
                lockIcon.classList.add('hidden');
            }
        }

        // Show/hide fast mode icon based on fast mode state
        if (fastIcon && dynamicCarousel) {
            const isFastMode = dynamicCarousel.dataset.fastMode === 'true';
            if (isFastMode) {
                fastIcon.classList.remove('hidden');
            } else {
                fastIcon.classList.add('hidden');
            }
        }

        // Show/hide cache icon when compiled prompt exists and use-cache is enabled
        // Show triangle exclamation if cache is expired
        if (cacheIcon && dynamicCarousel) {
            const useCache = dynamicCarousel.getAttribute('data-use-cache') !== 'false';
            if (useCache) {
                // Check if compiled prompt has expired
                const compiledPrompt = window.dynamicGenerationData?.compiled_prompt;
                const now = Date.now();
                const isExpired = compiledPrompt?.expiresAt ? now >= compiledPrompt.expiresAt : false;

                if (isExpired) {
                    // Show triangle exclamation for expired cache
                    cacheIcon.className = 'carousel-fast-icon fa-solid fa-triangle-exclamation';
                    cacheIcon.title = 'Cache Expired - Will Regenerate on Next Use';
                    cacheIcon.classList.remove('hidden');
                } else {
                    // Show check circle for valid cache
                    cacheIcon.className = 'carousel-fast-icon fa-regular fa-circle-check';
                    cacheIcon.title = 'Using Cache';
                    cacheIcon.classList.remove('hidden');
                }
            } else {
                cacheIcon.className = 'carousel-fast-icon fa-solid fa-triangle-exclamation';
                cacheIcon.classList.add('hidden');
            }
        }

        // Update active state
        if (carouselMode === 'current') {
            currentIndicator.classList.add('active');
            compiledIndicator.classList.remove('active');
        } else {
            currentIndicator.classList.remove('active');
            compiledIndicator.classList.add('active');
        }
    } else {
        indicators.classList.add('hidden');
        dynamicCarousel.classList.remove('has-indicators');
        if (lockIcon) {
            lockIcon.classList.add('hidden');
        }
        if (fastIcon) {
            fastIcon.classList.add('hidden');
        }
        if (cacheIcon) {
            cacheIcon.classList.add('hidden');
        }
    }
}

function toggleCarouselMode() {
    // Check if compiled prompt context exists
    const hasCompiledPrompt = window.dynamicGenerationData?.compiled_prompt?.context || compiledContextData;

    // Only toggle if compiled prompt exists
    if (!hasCompiledPrompt) return;

    // Toggle mode
    carouselMode = carouselMode === 'current' ? 'compiled' : 'current';

    // Update carousel with current mode's data
    // Use the mode parameter to ensure correct display
    if (carouselMode === 'compiled' && compiledContextData) {
        updateDynamicCarousel(compiledContextData, 'compiled');
    } else if (carouselMode === 'current') {
        // If switching to current context and no context is loaded, refresh it
        if (!currentContextData || (typeof currentContextData === 'object' && Object.keys(currentContextData).length === 0)) {
            requestDynamicContextResolution();
        } else {
            updateDynamicCarousel(currentContextData, 'current');
        }
    } else {
        // If data doesn't exist for the target mode, just update indicators
        updateCarouselIndicators();
    }
}

function initDynamicCarousel() {
    if (!dynamicCarousel) return;

    // Add hover listeners for pause/resume
    dynamicCarousel.addEventListener('mouseenter', pauseCarousel);
    dynamicCarousel.addEventListener('mouseleave', resumeCarousel);

    // Add click handler to toggle between modes (only left-click, not right-click for context menu)
    dynamicCarousel.addEventListener('click', (e) => {
        // Don't toggle on right-click (context menu)
        if (e.button === 2 || e.ctrlKey || e.metaKey) return;
        // Don't toggle if clicking on indicators (they have their own handlers if needed)
        if (e.target.closest('.carousel-indicators')) return;

        toggleCarouselMode();
    });
}

async function requestDynamicContextResolution() {
    try {
        if (!wsClient || !wsClient.isConnected()) {
            console.warn('⚠️ WebSocket not connected, cannot resolve dynamic context');
            return;
        }

        // Collect current button states
        const todBtn = document.getElementById('todBtn');
        const weatherBtn = document.getElementById('weatherBtn');
        const seasonBtn = document.getElementById('seasonBtn');
        const creativeBtn = document.getElementById('creativeBtn');

        const dynamicConfig = {
            tod: collectDynamicButtonState(todBtn),
            weather: collectDynamicButtonState(weatherBtn),
            season: collectDynamicButtonState(seasonBtn),
            creative: creativeBtn?.dataset.state === 'on'
        };

        // Add location if available
        if (weatherBtn && dynamicConfig.weather && weatherBtn.getAttribute('data-location')) {
            dynamicConfig.location = weatherBtn.getAttribute('data-location');
        }

        // Add disable_holiday if season is enabled and holiday toggle is false
        if (seasonBtn && dynamicConfig.season) {
            const observeHoliday = seasonBtn.dataset.toggleHoliday !== 'false';
            dynamicConfig.disable_holiday = !observeHoliday;
        }

        // Check if any dynamic values are enabled
        const hasAnyEnabled = Object.values(dynamicConfig).some(v => v !== false && v !== null && v !== undefined && v !== '');

        if (!hasAnyEnabled) {
            // Show empty state
            updateDynamicCarousel({});
            return;
        }

        const response = await wsClient.resolveDynamicContext(dynamicConfig);
        if (response) {
            // Store as current context and update carousel
            updateDynamicCarousel(response, 'current');
        }
    } catch (error) {
        console.error('❌ Error resolving dynamic context:', error);
    }
}

// Show loading state in carousel
function showCarouselLoadingState() {
    if (!dynamicCarousel) return;

    // Clear existing carousel items (but preserve indicators)
    const indicators = dynamicCarousel.querySelector('.carousel-indicators');
    dynamicCarousel.innerHTML = '';
    if (indicators) {
        dynamicCarousel.appendChild(indicators);
    }

    // Create loading item
    const loadingItem = document.createElement('div');
    loadingItem.className = 'carousel-item active';
    loadingItem.dataset.index = 0;

    const iconContainer = document.createElement('div');
    iconContainer.className = 'carousel-icon-container';
    const iconEl = document.createElement('i');
    iconEl.className = 'carousel-icon fa-solid fa-spinner-third fa-spin';
    iconContainer.appendChild(iconEl);

    const textEl = document.createElement('span');
    textEl.className = 'carousel-text';
    textEl.textContent = 'Please Wait...';

    loadingItem.appendChild(iconContainer);
    loadingItem.appendChild(textEl);

    dynamicCarousel.insertBefore(loadingItem, indicators || null);

    // Update carousel state
    carouselCurrentIndex = 0;
    carouselData = [{
        icon: 'fa-solid fa-spinner-third fa-spin',
        text: 'Please Wait...'
    }];
    updateCarouselIndicators();
}

// Debounced version to prevent excessive server requests
let debouncedRequestDynamicContextResolution = null;
function createDebouncedContextResolution() {
    // Show loading state immediately when function is called
    showCarouselLoadingState();

    // Create debounced function if it doesn't exist
    if (!debouncedRequestDynamicContextResolution) {
        debouncedRequestDynamicContextResolution = debounce(() => {
            requestDynamicContextResolution();
        }, 2500);
    }
    // Call the debounced function
    return debouncedRequestDynamicContextResolution();
}

// Holiday mapping from client values to server holiday names
const CLIENT_HOLIDAY_MAP = {
    'christmas': 'Christmas',
    'newyears': 'New Year\'s',
    'halloween': 'Halloween',
    'thanksgiving': 'Thanksgiving',
    'independenceday': 'Independence Day',
    'valentinesday': 'Valentine\'s Day',
    'easter': 'Easter',
    'chinesenewyear': 'Chinese New Year',
    'setsubun': 'Setsubun',
    'hinamatsuri': 'Hinamatsuri',
    'summerfestival': 'Summer Festival',
    'japanesenewyear': 'Japanese New Year',
    'cherryblossom': 'Cherry Blossom',
    'tanabatafestival': 'Star Festival',
    'goldenweek': 'Golden Week',
    'childrensday': 'Children\'s Day',
    'tsukimi': 'Mid-Autumn Festival',
    'obonfestival': 'Obon Festival',
    'nearest': 'nearest' // Special case for nearest holiday
};

// Function to get holiday date (simplified client-side version)
function getHolidayDateClient(holidayValue) {
    const now = new Date();
    const year = now.getFullYear();

    // Handle nearest holiday
    if (holidayValue === 'nearest') {
        // For simplicity, return current date for nearest - server will handle the actual logic
        return now;
    }

    const normalizedValue = (holidayValue || '').startsWith('true_')
        ? holidayValue.substring(5)
        : holidayValue;

    const holidayName = CLIENT_HOLIDAY_MAP[normalizedValue];
    if (!holidayName) return null;

    // Simplified holiday date calculation (basic implementation)
    const holidayDates = {
        'Christmas': new Date(year, 11, 25), // Dec 25
        'New Year\'s': new Date(year, 0, 1), // Jan 1
        'Halloween': new Date(year, 9, 31), // Oct 31
        'Thanksgiving': (() => {
            // Last Thursday in November (approximation)
            const thanksgiving = new Date(year, 10, 26);
            return thanksgiving;
        })(),
        'Independence Day': new Date(year, 6, 4), // Jul 4
        'Valentine\'s Day': new Date(year, 1, 14), // Feb 14
        'Easter': (() => {
            // Simplified - actual calculation varies
            return new Date(year, 3, 4); // Early April approximation
        })(),
        'Chinese New Year': new Date(year, 1, 5), // Early February approximation
        'Setsubun': new Date(year, 1, 3), // Feb 3
        'Hinamatsuri': new Date(year, 2, 3), // Mar 3
        'Summer Festival': new Date(year, 6, 20), // Late July approximation
        'Japanese New Year': new Date(year, 0, 1),
        'Cherry Blossom Season (Hanami)': new Date(year, 3, 1), // April
        'Star Festival': new Date(year, 6, 7), // Jul 7
        'Golden Week': new Date(year, 4, 29), // May 29
        'Children\'s Day': new Date(year, 4, 5), // May 5
        'Mid-Autumn Festival': new Date(year, 8, 15), // Mid-September
        'Obon Festival': new Date(year, 7, 15) // Mid-August
    };

    return holidayDates[holidayName] || null;
}

// Open time/date selection modal
function openTimeDateModal() {
    const modal = document.getElementById('timeDateModal');
    if (!modal) {
        return;
    }

    const todBtn = document.getElementById('todBtn');
    const currentOverride = todBtn ? todBtn.getAttribute('data-override') : null;

    const hourInput = document.getElementById('timeDateHour');
    const minuteInput = document.getElementById('timeDateMinute');
    const dayInput = document.getElementById('timeDateDay');
    const monthInput = document.getElementById('timeDateMonth');

    // Default to current date/time
    let targetDate = new Date();

    if (currentOverride) {
        if (currentOverride.includes('_')) {
            // TIME_DATE format
            const parts = currentOverride.split('_');
            let timePart = parts[0];
            const datePart = parts[1];

            // Strip % prefix if present
            if (timePart.startsWith('%')) {
                timePart = timePart.substring(1);
            }

            // Handle time part
            if (timePart && timePart.length === 4 && /^\d{4}$/.test(timePart)) {
                // HHmm format
                const hour = parseInt(timePart.substring(0, 2));
                const minute = parseInt(timePart.substring(2, 4));
                targetDate.setHours(hour, minute);
            }
            // Named time values (dawn, sunrise, etc.) leave time as current

            // Handle date part
            if (datePart) {
                if (datePart === 'tomorrow') {
                    targetDate.setDate(targetDate.getDate() + 1);
                } else if (datePart.length === 4 && /^\d{4}$/.test(datePart)) {
                    // MMDD numeric format
                    const month = parseInt(datePart.substring(0, 2));
                    const day = parseInt(datePart.substring(2, 4));
                    targetDate.setMonth(month - 1); // JavaScript months are 0-based
                    targetDate.setDate(day);
                } else if (CLIENT_HOLIDAY_MAP[datePart]) {
                    // Holiday date
                    const holidayDate = getHolidayDateClient('true_' + datePart);
                    if (holidayDate) {
                        targetDate = holidayDate;
                        // Preserve time from timePart if it was set (already stripped of % prefix above)
                        if (timePart && timePart.length === 4 && /^\d{4}$/.test(timePart)) {
                            const hour = parseInt(timePart.substring(0, 2));
                            const minute = parseInt(timePart.substring(2, 4));
                            targetDate.setHours(hour, minute);
                        }
                    }
                }
                // Other date values (today, nextweek, etc.) leave date as current
            }
        }
        // Single values without underscore are handled by current date/time
    }

    // Populate inputs with target date
    if (hourInput) hourInput.value = targetDate.getHours();
    if (minuteInput) minuteInput.value = targetDate.getMinutes();
    if (dayInput) dayInput.value = targetDate.getDate();
    if (monthInput) monthInput.value = targetDate.getMonth() + 1; // JavaScript months are 0-based

    openModal(modal);
}

// Handle time/date modal save
/**
 * Saves the time/date settings from the modal and applies them to the UI
 *
 * Validates all input fields (hour, minute, day, month), creates a Date object,
 * formats the values into the required override string format, and applies
 * the override to the time-of-day button. Shows success feedback to the user.
 *
 * @throws {Error} Implicitly throws validation errors via toast notifications
 */
function saveTimeDateModal() {
    const hour = parseInt(document.getElementById('timeDateHour').value);
    const minute = parseInt(document.getElementById('timeDateMinute').value);
    const day = parseInt(document.getElementById('timeDateDay').value);
    const month = parseInt(document.getElementById('timeDateMonth').value);

    // Validate inputs
    if (isNaN(hour) || hour < 0 || hour > 23) {
        showGlassToast('error', null, 'Invalid hour. Must be between 0-23.', false, undefined, '<i class="fas fa-clock"></i>');
        return;
    }
    if (isNaN(minute) || minute < 0 || minute > 59) {
        showGlassToast('error', null, 'Invalid minute. Must be between 0-59.', false, undefined, '<i class="fas fa-clock"></i>');
        return;
    }
    if (isNaN(day) || day < 1 || day > 31) {
        showGlassToast('error', null, 'Invalid day. Must be between 1-31.', false, undefined, '<i class="fas fa-clock"></i>');
        return;
    }
    if (isNaN(month) || month < 1 || month > 12) {
        showGlassToast('error', null, 'Invalid month. Must be between 1-12.', false, undefined, '<i class="fas fa-clock"></i>');
        return;
    }

    // Create a date object with the selected values (using current year)
    const now = new Date();
    const selectedDate = new Date(now.getFullYear(), month - 1, day, hour, minute);

    // Create a custom override value in the format %HHmm_MMDD
    const formattedHour = hour.toString().padStart(2, '0');
    const formattedMinute = minute.toString().padStart(2, '0');
    const formattedDay = day.toString().padStart(2, '0');
    const formattedMonth = month.toString().padStart(2, '0');
    const timeDateValue = `%${formattedHour}${formattedMinute}_${formattedMonth}${formattedDay}`;

    // Set the dynamic override on the time of day button
    setDynamicOverride(document.getElementById('todBtn'), timeDateValue);

    // Close the modal
    const modal = document.getElementById('timeDateModal');
    closeModal(modal);

    showGlassToast('success', null, `Time/Date set to ${selectedDate.toLocaleString()}`, undefined, undefined, '<i class="fas fa-clock"></i>');
}

// WEATHER LOCATION MODAL FUNCTIONS

// Open the weather location modal
function openWeatherLocationModal() {
    const modal = document.getElementById('weatherLocationModal');
    if (!modal) {
        return;
    }

    // Reset form state
    const input = document.getElementById('weatherLocationInput');
    const matchDisplay = document.getElementById('weatherLocationMatch');
    const saveBtn = document.getElementById('saveWeatherLocationBtn');

    input.value = '';
    matchDisplay.textContent = 'Enter a city name and click Verify to see the matched location.';
    matchDisplay.className = 'weather-location-match';
    saveBtn.disabled = true;
    saveBtn.dataset.location = '';

    // Show the modal
    openModal(modal);
}

// Verify weather location via WebSocket
async function verifyWeatherLocation() {
    const input = document.getElementById('weatherLocationInput');
    const matchDisplay = document.getElementById('weatherLocationMatch');
    const saveBtn = document.getElementById('saveWeatherLocationBtn');

    const cityName = input.value.trim();
    if (!cityName) {
        matchDisplay.textContent = 'Please enter a city name.';
        matchDisplay.className = 'weather-location-match error';
        saveBtn.disabled = true;
        return;
    }

    try {
        matchDisplay.textContent = 'Searching...';
        matchDisplay.className = 'weather-location-match loading';

        // Send WebSocket request for city lookup
        if (!window.wsClient || !window.wsClient.isConnected()) {
            throw new Error('WebSocket not connected');
        }

        const response = await window.wsClient.lookupCity(cityName);

        if (response && response.longitude !== undefined && response.latitude !== undefined) {
            const result = response;

            // Display matched location with current time
            const locationText = `${result.city || cityName}, ${result.state || ''} ${result.country || ''}`.trim();
            let displayText = `Found: ${locationText}`;

            // Add current time if timezone is available
            if (result.timezone) {
                try {
                    const now = new Date();
                    const timeString = now.toLocaleTimeString('en-US', {
                        timeZone: result.timezone,
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: true
                    });
                    displayText += ` (Current time: ${timeString})`;
                } catch (error) {
                    console.warn('Failed to format time for timezone:', result.timezone, error);
                }
            }

            matchDisplay.textContent = displayText;
            matchDisplay.className = 'weather-location-match success';

            // Enable save button and store coordinates
            saveBtn.disabled = false;
            saveBtn.dataset.location = `${result.longitude}_${result.latitude}`;
            saveBtn.dataset.displayName = locationText;
        } else {
            matchDisplay.textContent = 'City not found. Please try a different name.';
            matchDisplay.className = 'weather-location-match error';
            saveBtn.disabled = true;
        }
    } catch (error) {
        console.error('City lookup error:', error);
        matchDisplay.textContent = error.message || 'Error searching for city. Please try again.';
        matchDisplay.className = 'weather-location-match error';
        saveBtn.disabled = true;
    }
}

// Save weather location
function saveWeatherLocation() {
    const saveBtn = document.getElementById('saveWeatherLocationBtn');
    const locationData = saveBtn.dataset.location;
    const displayName = saveBtn.dataset.displayName;

    if (!locationData) {
        showGlassToast('error', null, 'No location to save.', false, undefined, '<i class="fas fa-location-dot-slash"></i>');
        return;
    }

    // Set the location on the weather button
    const weatherBtn = document.getElementById('weatherBtn');
    if (weatherBtn) {
        weatherBtn.setAttribute('data-location', locationData);
        weatherBtn.dataset.locationDisplay = displayName;

        // Also set it as active if not already
        weatherBtn.dataset.state = 'on';
        weatherBtn.classList.add('active');

        showGlassToast('success', null, `Location set to ${displayName}`, undefined, undefined, '<i class="fas fa-map-marker-alt"></i>');

        // Update status icons to reflect the location change
        updatePromptStatusIcons();

        createDebouncedContextResolution();
    }

    // Close the modal
    const modal = document.getElementById('weatherLocationModal');
    closeModal(modal);
}

// Clear weather location
function clearWeatherLocation() {
    const weatherBtn = document.getElementById('weatherBtn');
    if (weatherBtn) {
        const hadLocation = weatherBtn.hasAttribute('data-location');
        weatherBtn.removeAttribute('data-location');
        delete weatherBtn.dataset.locationDisplay;

        if (hadLocation) {
            updatePromptStatusIcons();
            updateDynamicGenerationToggleBtn();
            createDebouncedContextResolution();
        }
    }
}

// Set current location using browser geolocation, fallback to server-side IP lookup
function setCurrentLocation() {
    if (!navigator.geolocation) {
        showGlassToast('error', null, 'Geolocation is not supported by this browser', false, undefined, '<i class="fas fa-location-dot-slash"></i>');
    }

    showGlassToast('info', null, 'Getting current location...', false, undefined, '<i class="fas fa-location-dot"></i>');

    // Try GPS/network location first, then fallback to server IP lookup
    function tryGPSLocation(options) {
        let timeoutId;

        const successCallback = function (position) {
            clearTimeout(timeoutId);
            const latitude = position.coords.latitude;
            const longitude = position.coords.longitude;

            // Set the location on the weather button
            const weatherBtn = document.getElementById('weatherBtn');
            if (weatherBtn) {
                const locationData = `${longitude}_${latitude}`;
                const displayName = `Current Location (${latitude.toFixed(4)}, ${longitude.toFixed(4)})`;

                weatherBtn.setAttribute('data-location', locationData);
                weatherBtn.dataset.locationDisplay = displayName;

                // Also set it as active if not already
                weatherBtn.dataset.state = 'on';
                weatherBtn.classList.add('active');

                showGlassToast('success', null, `Location set to current location`, undefined, undefined, '<i class="fas fa-map-marker-alt"></i>');

                // Update status icons to reflect the location change
                updatePromptStatusIcons();

                createDebouncedContextResolution();
            }
        };

        const errorCallback = function (error) {
            clearTimeout(timeoutId);

            switch (error.code) {
                case error.PERMISSION_DENIED:
                    showGlassToast('error', null, 'Location access denied. Please allow location access in your browser settings.', false, undefined, '<i class="fas fa-location-dot-slash"></i>');
                    break;
                case error.POSITION_UNAVAILABLE:
                case error.TIMEOUT:
                    // Browser geolocation failed, use server-side IP lookup
                    setIPLocation();
                    break;
            }
        };

        // Set a timeout to handle silent failures (some browsers don't call error callback)
        timeoutId = setTimeout(() => {
            setIPLocation();
        }, options.timeout + 1000);

        navigator.geolocation.getCurrentPosition(successCallback, errorCallback, options);
    }

    // Start with high accuracy GPS/network location
    tryGPSLocation({
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 300000 // 5 minutes
    });
}

// Set location using server-side IP geolocation (skip GPS)
function setIPLocation() {
    const weatherBtn = document.getElementById('weatherBtn');
    if (weatherBtn) {
        weatherBtn.setAttribute('data-location', 'CLIENT');
        weatherBtn.dataset.locationDisplay = 'Current Location (GeoIP)';

        // Also set it as active if not already
        weatherBtn.dataset.state = 'on';
        weatherBtn.classList.add('active');

        showGlassToast('success', null, 'Location set to IP-based geolocation', undefined, undefined, '<i class="fas fa-map-marker-alt"></i>');

        // Update status icons to reflect the location change
        updatePromptStatusIcons();

        createDebouncedContextResolution();
    }
}

// API KEY MANAGER MODAL
function resetApiKeyModalState() {
    apiKeyModalState.services = [];
    apiKeyModalState.originalSelections = {};
    apiKeyModalState.pendingSelections = {};
    apiKeyModalState.dom = new Map();
}

function openApiKeyModal() {
    const modal = document.getElementById('apiKeyModal');
    if (!modal) return;

    apiKeyModalState.isLoading = true;
    updateApiKeyModalStatus('Loading services...');
    updateApiKeySaveButtonState();
    openModal(modal);
    loadApiKeyModalData(true);
}

async function loadApiKeyModalData(showToastOnError = true) {
    apiKeyModalState.isLoading = true;
    updateApiKeySaveButtonState();

    try {
        if (!window.wsClient || !window.wsClient.isConnected()) {
            throw new Error('WebSocket not connected. Please reconnect and try again.');
        }

        const data = await window.wsClient.sendMessage('get_api_key_services', {});
        resetApiKeyModalState();
        apiKeyModalState.services = Array.isArray(data?.services) ? data.services : [];

        apiKeyModalState.services.forEach(service => {
            const hasKeys = Array.isArray(service.keys) && service.keys.length > 0;
            const fallbackIndex = hasKeys && Number.isInteger(service.selectedIndex) ? service.selectedIndex : 0;
            if (!hasKeys) {
                service.missingKeys = true;
            }
            apiKeyModalState.originalSelections[service.id] = hasKeys ? fallbackIndex : null;
            apiKeyModalState.pendingSelections[service.id] = hasKeys ? fallbackIndex : null;
        });

        renderApiKeyServices();

        if (apiKeyModalState.services.length === 0) {
            updateApiKeyModalStatus('No Services Available.');
        } else {
            updateApiKeyModalStatus('Service Keys are stored in `secure.config.json`, Select the active key for each service.');
        }
    } catch (error) {
        console.error('Service Key modal load error:', error);
        const message = error.message || 'Failed to load services.';
        updateApiKeyModalStatus(message);
        if (showToastOnError) {
            showGlassToast('error', null, message, false, undefined, '<i class="fas fa-key-skeleton-left-right"></i>');
        }
    } finally {
        apiKeyModalState.isLoading = false;
        updateApiKeySaveButtonState();
    }
}

function renderApiKeyServices() {
    const container = document.getElementById('apiKeyServicesContainer');
    if (!container) return;

    container.innerHTML = '';
    apiKeyModalState.dom = new Map();

    if (!apiKeyModalState.services.length) {
        const empty = document.createElement('p');
        empty.className = 'text-muted';
        empty.textContent = 'No services available.';
        container.appendChild(empty);
        return;
    }

    apiKeyModalState.services.forEach(service => {
        const card = document.createElement('div');
        card.className = 'manual-modal-form-section';

        const title = document.createElement('label');
        const iconClass = escapeHtmlAttribute(service.icon || 'fas fa-key-skeleton-left-right');
        title.innerHTML = `<i class="${iconClass}"></i> ${escapeHtml(service.label || service.id)}`;
        card.appendChild(title);

        if (service.description) {
            const description = document.createElement('p');
            description.className = 'text-muted';
            description.textContent = service.description;
            card.appendChild(description);
        }

        const dropdown = document.createElement('div');
        dropdown.className = 'custom-dropdown dark';

        const dropdownButton = document.createElement('button');
        dropdownButton.type = 'button';
        dropdownButton.className = 'btn-secondary';
        dropdownButton.id = `apiKeyDropdownBtn-${service.id}`;

        const selectedLabel = document.createElement('span');
        selectedLabel.id = `apiKeyDropdownSelected-${service.id}`;
        selectedLabel.textContent = getServiceDisplayName(service);
        dropdownButton.appendChild(selectedLabel);

        const chevron = document.createElement('i');
        chevron.className = 'fas fa-chevron-down';
        dropdownButton.appendChild(chevron);

        const dropdownMenu = document.createElement('div');
        dropdownMenu.id = `apiKeyDropdownMenu-${service.id}`;
        dropdownMenu.className = 'custom-dropdown-menu hidden';

        dropdown.appendChild(dropdownButton);
        dropdown.appendChild(dropdownMenu);
        card.appendChild(dropdown);

        const fingerprint = document.createElement('div');
        fingerprint.className = 'text-muted';
        fingerprint.id = `apiKeyFingerprint-${service.id}`;
        fingerprint.textContent = getServiceFingerprintText(service);
        card.appendChild(fingerprint);

        if (service.requiresRestart) {
            const restartNote = document.createElement('div');
            restartNote.className = 'text-muted';
            restartNote.innerHTML = '<i class="fas fa-arrows-rotate"></i> Service restarts after saving changes.';
            card.appendChild(restartNote);
        }

        if (service.missingKeys) {
            const warning = document.createElement('div');
            warning.className = 'text-muted';
            warning.textContent = 'No Service keys configured for this service.';
            card.appendChild(warning);
            dropdownButton.disabled = true;
        } else {
            setupDropdown(
                dropdown,
                dropdownButton,
                dropdownMenu,
                () => renderApiKeyDropdownOptions(service.id),
                () => apiKeyModalState.pendingSelections[service.id],
                { preventFocusTransfer: true }
            );
        }

        apiKeyModalState.dom.set(service.id, {
            selectedLabel,
            fingerprint,
            dropdownButton,
            dropdownMenu
        });

        container.appendChild(card);
    });
}

function getServiceDisplayName(service) {
    if (service.missingKeys) {
        return 'No Service Keys configured';
    }

    const selection = apiKeyModalState.pendingSelections[service.id];
    if (selection === null || selection === undefined) {
        return 'Select a key';
    }

    const key = service.keys?.find(k => k.index === selection);
    if (key && key.name) {
        return key.name;
    }

    return `Key ${selection + 1}`;
}

function getServiceFingerprintText(service) {
    if (service.missingKeys) {
        return 'Active key: —';
    }

    const selection = apiKeyModalState.pendingSelections[service.id];
    if (selection === null || selection === undefined) {
        return 'Active key: —';
    }

    const key = service.keys?.find(k => k.index === selection);
    if (key && key.fingerprint) {
        return `Active key: ${key.fingerprint}`;
    }

    return 'Active key: —';
}

function renderApiKeyDropdownOptions(serviceId) {
    const service = apiKeyModalState.services.find(s => s.id === serviceId);
    const refs = apiKeyModalState.dom.get(serviceId);
    if (!service || !refs || !refs.dropdownMenu) return;

    const menu = refs.dropdownMenu;
    menu.innerHTML = '';

    if (!Array.isArray(service.keys) || service.keys.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'custom-dropdown-option';
        empty.textContent = 'No keys configured';
        menu.appendChild(empty);

        // Add "Add new Key" option even when no keys exist
        const addOption = document.createElement('div');
        addOption.className = 'custom-dropdown-option';
        addOption.innerHTML = '<i class="fas fa-plus"></i> Add new Key';
        addOption.addEventListener('click', (e) => {
            e.preventDefault();
            closeDropdown(menu, refs.dropdownButton);
            showGlassToast('info', null, 'Add new keys manually in secure.config.json', false, undefined, '<i class="fas fa-key"></i>');
        });
        menu.appendChild(addOption);
        return;
    }

    const current = apiKeyModalState.pendingSelections[serviceId];
    service.keys.forEach(key => {
        const option = document.createElement('div');
        option.className = 'custom-dropdown-option' + (current === key.index ? ' selected' : '');
        option.dataset.value = key.index;

        const nameLine = document.createElement('div');
        nameLine.textContent = key.name || `Key ${key.index + 1}`;
        option.appendChild(nameLine);

        if (key.fingerprint) {
            const fpLine = document.createElement('div');
            fpLine.className = 'text-muted';
            fpLine.textContent = key.fingerprint;
            option.appendChild(fpLine);
        }

        const handler = (e) => {
            e.preventDefault();
            selectApiKeyOption(serviceId, key.index);
            closeDropdown(menu, refs.dropdownButton);
        };

        option.addEventListener('click', handler);
        option.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' || e.key === ' ') {
                handler(e);
            }
        });

        menu.appendChild(option);
    });

    // Add separator and "Add new Key" option
    const separator = document.createElement('div');
    separator.className = 'custom-dropdown-separator';
    menu.appendChild(separator);

    const addOption = document.createElement('div');
    addOption.className = 'custom-dropdown-option';
    addOption.innerHTML = '<i class="fas fa-plus"></i> Add new Key';
    addOption.addEventListener('click', (e) => {
        e.preventDefault();
        closeDropdown(menu, refs.dropdownButton);
        openAddApiKeyModal(serviceId);
    });
    menu.appendChild(addOption);
}

function selectApiKeyOption(serviceId, index) {
    const service = apiKeyModalState.services.find(s => s.id === serviceId);
    if (!service || service.missingKeys) return;

    const normalizedIndex = Number(index);
    if (!Number.isInteger(normalizedIndex)) return;

    apiKeyModalState.pendingSelections[serviceId] = normalizedIndex;
    service.selectedIndex = normalizedIndex;

    const key = service.keys?.find(k => k.index === normalizedIndex);
    if (key) {
        service.selectedName = key.name;
        service.selectedFingerprint = key.fingerprint;
    }

    const refs = apiKeyModalState.dom.get(serviceId);
    if (refs?.selectedLabel) {
        refs.selectedLabel.textContent = key?.name || `Key ${normalizedIndex + 1}`;
    }
    if (refs?.fingerprint) {
        refs.fingerprint.textContent = key?.fingerprint ? `Active key: ${key.fingerprint}` : 'Active key: —';
    }

    updateApiKeySaveButtonState();
}

function getApiKeyModalChanges() {
    return Object.entries(apiKeyModalState.pendingSelections)
        .filter(([serviceId, index]) => {
            const original = apiKeyModalState.originalSelections[serviceId];
            return index !== null && index !== undefined && original !== index;
        })
        .map(([serviceId, index]) => ({ serviceId, index }));
}

function updateApiKeySaveButtonState() {
    const refreshBtn = document.getElementById('refreshApiKeyModalBtn');
    if (refreshBtn) {
        refreshBtn.disabled = apiKeyModalState.isLoading;
    }
}

function updateApiKeyModalStatus(message) {
    const status = document.getElementById('apiKeyModalStatus');
    if (!status) return;

    if (message) {
        status.textContent = message;
        status.classList.remove('hidden');
    } else {
        status.textContent = '';
        status.classList.add('hidden');
    }
}

async function handleApiKeyModalClose() {
    const changes = getApiKeyModalChanges();
    if (changes.length === 0) {
        const modal = document.getElementById('apiKeyModal');
        if (modal) {
            closeModal(modal);
        }
        return;
    }

    // Build confirmation dialog message
    const changeList = changes.map(change => {
        const service = apiKeyModalState.services.find(s => s.id === change.serviceId);
        const serviceLabel = service?.label || change.serviceId;
        const key = service?.keys?.find(k => k.index === change.index);
        const keyName = key?.name || `Key ${change.index + 1}`;
        const fingerprint = key?.fingerprint || '••••';
        const requiresRestart = service?.requiresRestart === true;

        return {
            serviceLabel,
            keyName,
            fingerprint,
            requiresRestart
        };
    });

    const servicesNeedingRestart = changeList.filter(c => c.requiresRestart);
    const needsRestart = servicesNeedingRestart.length > 0;

    let message = 'Do you want to apply changes to the Keychain:<br><br>';
    changeList.forEach(change => {
        const restartMarker = change.requiresRestart ? ' <span style="color: #ff8c00;">(requires reload)</span>' : '';
        message += `  • ${escapeHtml(change.serviceLabel)} → ${escapeHtml(change.keyName)} (${escapeHtml(change.fingerprint)})${restartMarker}<br>`;
    });

    if (needsRestart) {
        const serviceNames = servicesNeedingRestart.map(c => escapeHtml(c.serviceLabel)).join(', ');
        message += `<br><br><span style="color: #ff8c00;">* ${serviceNames} will reload its client and any active tasks will be halted!</span>`;
    }

    // Show confirmation dialog
    const result = await showConfirmationDialog(message, [
        {
            text: needsRestart ? 'Apply & Reload' : 'Apply',
            value: 'apply',
            className: 'btn-primary',
            icon: needsRestart ? 'fas fa-arrows-rotate' : 'fas fa-save'
        },
        {
            text: 'Revert',
            value: 'revert',
            className: 'btn-secondary',
            icon: 'fas fa-undo'
        }
    ]);

    if (result === 'apply') {
        await saveApiKeySelections();
        const modal = document.getElementById('apiKeyModal');
        if (modal) {
            closeModal(modal);
        }
    } else if (result === 'revert') {
        // Revert pending selections to original
        Object.keys(apiKeyModalState.originalSelections).forEach(serviceId => {
            apiKeyModalState.pendingSelections[serviceId] = apiKeyModalState.originalSelections[serviceId];
        });
        renderApiKeyServices();
        updateApiKeySaveButtonState();
    }
    // If result is null (cancelled), do nothing
}

async function saveApiKeySelections() {
    const changes = getApiKeyModalChanges();
    if (changes.length === 0) {
        showGlassToast('info', null, 'No Keychain changes to save.', false, undefined, '<i class="fas fa-key-skeleton-left-right"></i>');
        return;
    }

    apiKeyModalState.isLoading = true;
    updateApiKeyModalStatus('Saving Keychain...');
    updateApiKeySaveButtonState();

    try {
        if (!window.wsClient || !window.wsClient.isConnected()) {
            throw new Error('WebSocket not connected. Please reconnect and try again.');
        }

        const updatesPayload = changes.map(change => ({
            service: change.serviceId,
            index: change.index
        }));

        const data = await window.wsClient.sendMessage('update_api_key_selections', {
            updates: updatesPayload
        });

        if (Array.isArray(data?.restartedServices)) {
            data.restartedServices.forEach(serviceId => {
                const service = apiKeyModalState.services.find(s => s.id === serviceId);
                const label = service?.label || serviceId;
                showGlassToast('success', null, `${label} Service was restarted (Updated Keychain)`, false, undefined, '<i class="fas fa-arrows-rotate"></i>');
            });
        }

        showGlassToast('success', null, 'keychain was updated.', false, undefined, '<i class="fas fa-key-skeleton-left-right"></i>');
        await loadApiKeyModalData(false);
        updateApiKeyModalStatus('Keychain was saved.');
    } catch (error) {
        console.error('Keychain save error:', error);
        const message = error.message || 'Failed to save service keychain.';
        updateApiKeyModalStatus(message);
        showGlassToast('error', null, message, false, undefined, '<i class="fas fa-key-skeleton-left-right"></i>');
    } finally {
        apiKeyModalState.isLoading = false;
        updateApiKeySaveButtonState();
    }
}

// ADD NEW API KEY MODAL FUNCTIONS
let addApiKeyModalState = {
    serviceId: null,
    isLoading: false
};

function openAddApiKeyModal(serviceId) {
    const modal = document.getElementById('addApiKeyModal');
    if (!modal) return;

    addApiKeyModalState.serviceId = serviceId;
    addApiKeyModalState.isLoading = false;

    const nameInput = document.getElementById('addApiKeyNameInput');
    const valueInput = document.getElementById('addApiKeyValueInput');
    const statusEl = document.getElementById('addApiKeyModalStatus');

    if (nameInput) nameInput.value = '';
    if (valueInput) valueInput.value = '';
    if (statusEl) {
        statusEl.textContent = '';
        statusEl.classList.add('hidden');
    }

    const service = apiKeyModalState.services.find(s => s.id === serviceId);
    if (service) {
        const modalTitle = modal.querySelector('.modal-window-title-main span');
        if (modalTitle) {
            modalTitle.textContent = `Add New Key - ${service.label}`;
        }
    }

    updateAddApiKeyButtonState();
    openModal(modal);

    // Focus on name input
    if (nameInput) {
        setTimeout(() => nameInput.focus(), 100);
    }
}

function closeAddApiKeyModal() {
    const modal = document.getElementById('addApiKeyModal');
    if (modal) {
        closeModal(modal);
    }
    addApiKeyModalState.serviceId = null;
    addApiKeyModalState.isLoading = false;
}

function updateAddApiKeyModalStatus(message, isError = false) {
    const status = document.getElementById('addApiKeyModalStatus');
    if (!status) return;

    if (message) {
        status.textContent = message;
        status.className = isError ? 'text-danger' : 'text-muted';
        status.classList.remove('hidden');
    } else {
        status.textContent = '';
        status.classList.add('hidden');
    }
}

function updateAddApiKeyButtonState() {
    const saveBtn = document.getElementById('saveNewApiKeyBtn');
    if (saveBtn) {
        const nameInput = document.getElementById('addApiKeyNameInput');
        const valueInput = document.getElementById('addApiKeyValueInput');
        const hasName = nameInput && nameInput.value.trim().length > 0;
        const hasValue = valueInput && valueInput.value.trim().length > 0;
        saveBtn.disabled = addApiKeyModalState.isLoading || !hasName || !hasValue;
    }
}

async function saveNewApiKey() {
    const nameInput = document.getElementById('addApiKeyNameInput');
    const valueInput = document.getElementById('addApiKeyValueInput');

    if (!nameInput || !valueInput) return;

    const name = nameInput.value.trim();
    const apiKey = valueInput.value.trim();

    if (!name) {
        updateAddApiKeyModalStatus('Service Key Name is required.', true);
        nameInput.focus();
        return;
    }

    if (!apiKey) {
        updateAddApiKeyModalStatus('Service Key is required.', true);
        valueInput.focus();
        return;
    }

    if (!addApiKeyModalState.serviceId) {
        updateAddApiKeyModalStatus('Service ID is missing.', true);
        return;
    }

    addApiKeyModalState.isLoading = true;
    updateAddApiKeyModalStatus('Adding new Key to keychain...');
    updateAddApiKeyButtonState();

    try {
        if (!window.wsClient || !window.wsClient.isConnected()) {
            throw new Error('WebSocket not connected. Please reconnect and try again.');
        }

        const data = await window.wsClient.sendMessage('add_api_key', {
            service: addApiKeyModalState.serviceId,
            name: name,
            apiKey: apiKey
        });

        if (data?.success) {
            showGlassToast('success', null, 'New Service Key added successfully', false, undefined, '<i class="fas fa-key-skeleton-left-right"></i>');
            closeAddApiKeyModal();
            // Reload the API key modal data to show the new key
            await loadApiKeyModalData(false);
        } else {
            throw new Error(data?.error || 'Failed to add new key');
        }
    } catch (error) {
        console.error('Add API key error:', error);
        const message = error.message || 'Failed to add new key.';
        updateAddApiKeyModalStatus(message, true);
        showGlassToast('error', null, message, false, undefined, '<i class="fas fa-key-skeleton-left-right"></i>');
    } finally {
        addApiKeyModalState.isLoading = false;
        updateAddApiKeyButtonState();
    }
}

// TEXT REPLACEMENT LOCK MODAL FUNCTIONS
