// Metadata dialog functions
function showMetadataDialog() {
    if (currentImage && currentImage.metadata && metadataDialog) {
        populateDialogMetadataTable(currentImage.metadata);
        openModal(metadataDialog);
    }
}

function hideMetadataDialog() {
    if (metadataDialog) {
        metadataDialog.classList.add('hidden');
    }

    // Hide expanded sections
    if (dialogPromptExpanded) dialogPromptExpanded.classList.add('hidden');
    if (dialogUcExpanded) dialogUcExpanded.classList.add('hidden');
}
function populateDialogMetadataTable(metadata) {
    // Type and Name
    const typeElement = document.getElementById('dialogMetadataType');
    const nameElement = document.getElementById('dialogMetadataName');

    if (typeElement && nameElement) {
        if (metadata.request_type) {
            typeElement.textContent = formatRequestType(metadata.request_type);

            // Show/hide name field based on preset_name availability
            const nameCell = nameElement.closest('.metadata-cell');
            if (metadata.preset_name) {
                nameElement.textContent = metadata.preset_name;
                if (nameCell) nameCell.classList.remove('hidden');
            } else {
                if (nameCell) nameCell.classList.add('hidden');
            }
        } else {
            typeElement.textContent = '-';
            const nameCell = nameElement.closest('.metadata-cell');
            if (nameCell) nameCell.classList.add('hidden');
        }
    }

    // Model
    const modelElement = document.getElementById('dialogMetadataModel');
    if (modelElement) {
        modelElement.textContent = metadata.model_display_name || metadata.model || '-';
    }

    // Resolution
    const resolutionElement = document.getElementById('dialogMetadataResolution');
    if (resolutionElement) {
        if (metadata.resolution) {
            let resolutionText = formatResolution(metadata.resolution);
            if (metadata.upscaled) {
                resolutionElement.innerHTML = `${resolutionText} <span class="badge upscaled-badge">Upscaled</span>`;
            } else {
                resolutionElement.textContent = resolutionText;
            }
        } else if (metadata.width && metadata.height) {
            let dimensionText = `${metadata.width} × ${metadata.height}`;
            if (metadata.upscaled) {
                resolutionElement.innerHTML = `${dimensionText} <span class="badge upscaled-badge">Upscaled</span>`;
            } else {
                resolutionElement.textContent = dimensionText;
            }
        } else {
            resolutionElement.textContent = '-';
        }
    }

    // Steps
    const stepsElement = document.getElementById('dialogMetadataSteps');
    if (stepsElement) {
        const stepsText = metadata.steps || '-';
        if (metadata.skip_cfg_above_sigma !== null && metadata.skip_cfg_above_sigma !== undefined) {
            stepsElement.innerHTML = `${stepsText} <i class="fas fa-tint variety-icon" title="Variety+ enabled"></i>`;
        } else {
            stepsElement.textContent = stepsText;
        }
    }

    // Seeds - Handle display logic
    const seed1Element = document.getElementById('dialogMetadataSeed1');
    const seed2Element = document.getElementById('dialogMetadataSeed2');

    if (seed1Element && seed2Element) {
        // Find the label elements more safely
        const seed1Cell = seed1Element.closest('.metadata-cell');
        const seed2Cell = seed2Element.closest('.metadata-cell');
        const seed1Label = seed1Cell ? seed1Cell.querySelector('.metadata-label') : null;
        const seed2Label = seed2Cell ? seed2Cell.querySelector('.metadata-label') : null;

        if (seed1Label && seed2Label) {
            // Check if this is both seeds
            const hasLayer2Seed = metadata.layer2Seed !== undefined;

            if (hasLayer2Seed) {
                seed1Label.textContent = 'Seed 1';
                seed2Label.textContent = 'Seed 2';
                seed1Element.textContent = metadata.layer1Seed || '-';
                seed2Element.textContent = metadata.layer2Seed || '-';
                seed1Cell.classList.remove('hidden');
                seed2Cell.classList.remove('hidden');
            } else {
                // Single seed - hide seed 2 and rename seed 1
                seed1Label.textContent = 'Seed';
                seed1Element.textContent = metadata.layer1Seed || metadata.seed || '-';
                seed1Cell.classList.remove('hidden');
                seed2Cell.classList.add('hidden');
            }
        }
    }

    // Guidance
    const guidanceElement = document.getElementById('dialogMetadataGuidance');
    if (guidanceElement) {
        guidanceElement.textContent = metadata.scale || '-';
    }

    // Rescale
    const rescaleElement = document.getElementById('dialogMetadataRescale');
    if (rescaleElement) {
        rescaleElement.textContent = metadata.cfg_rescale || '-';
    }

    // Sampler
    const samplerElement = document.getElementById('dialogMetadataSampler');
    if (samplerElement) {
        const samplerObj = getSamplerMeta(metadata.sampler);
        samplerElement.textContent = samplerObj ? samplerObj.display : (metadata.sampler || '-');
    }

    // Noise Schedule
    const noiseScheduleElement = document.getElementById('dialogMetadataNoiseSchedule');
    if (noiseScheduleElement) {
        const noiseObj = getNoiseMeta(metadata.noise_schedule);
        noiseScheduleElement.textContent = noiseObj ? noiseObj.display : (metadata.noise_schedule || '-');
    }

    // Store prompt and UC content for expandable sections
    if (dialogPromptContent) {
        dialogPromptContent.textContent = metadata.prompt || 'No prompt available';
    }
    if (dialogUcContent) {
        dialogUcContent.textContent = metadata.uc || 'No undesired content specified';
    }
}

function toggleDialogExpanded(type) {
    if (type === 'prompt' && dialogPromptExpanded && dialogUcExpanded) {
        if (dialogPromptExpanded.classList.contains('hidden')) {
            dialogPromptExpanded.classList.remove('hidden');
            dialogUcExpanded.classList.add('hidden');
        } else {
            dialogPromptExpanded.classList.add('hidden');
        }
    } else if (type === 'uc' && dialogUcExpanded && dialogPromptExpanded) {
        if (dialogUcExpanded.classList.contains('hidden')) {
            dialogUcExpanded.classList.remove('hidden');
            dialogPromptExpanded.classList.add('hidden');
        } else {
            dialogUcExpanded.classList.add('hidden');
        }
    }
}

// Reset metadata table to default state
function resetMetadataTable() {
    // Reset all metadata values to '-'
    const metadataElements = [
        'metadataType', 'metadataName', 'metadataModel', 'metadataResolution',
        'metadataSteps', 'metadataSeed1', 'metadataSeed2', 'metadataGuidance',
        'metadataRescale', 'metadataSampler', 'metadataNoiseSchedule'
    ];

    metadataElements.forEach(id => {
        const element = document.getElementById(id);
        if (element) {
            element.textContent = '-';
        }
    });

    // Show name field by default when resetting
    const nameElement = document.getElementById('metadataName');
    if (nameElement) {
        const nameCell = nameElement.closest('.metadata-cell');
        if (nameCell) nameCell.classList.remove('hidden');
    }

    // Reset seed labels and show both cells
    const seed1Element = document.getElementById('metadataSeed1');
    const seed2Element = document.getElementById('metadataSeed2');

    if (seed1Element && seed2Element) {
        const seed1Cell = seed1Element.closest('.metadata-cell');
        const seed2Cell = seed2Element.closest('.metadata-cell');
        const seed1Label = seed1Cell ? seed1Cell.querySelector('.metadata-label') : null;
        const seed2Label = seed2Cell ? seed2Cell.querySelector('.metadata-label') : null;

        if (seed1Label && seed2Label) {
            seed1Label.textContent = 'Seed 1';
            seed2Label.textContent = 'Seed 2';
            seed1Cell.classList.remove('hidden');
            seed2Cell.classList.remove('hidden');
        }
    }

    // Hide prompt/UC buttons
    const promptBtn = document.getElementById('promptBtn');
    const ucBtn = document.getElementById('ucBtn');
    if (promptBtn) promptBtn.classList.add('hidden');
    if (ucBtn) ucBtn.classList.add('hidden');

    // Hide expanded sections
    const expandedSections = document.querySelectorAll('.metadata-expanded');
    expandedSections.forEach(section => {
        section.classList.add('hidden');
    });
}

// Clear seed function
function clearSeed() {
    if (manualSeed && manualSeed.value) {
        manualSeed.value = '';
        manualSeed.focus();

        // Reset sprout seed button state if it was active
        if (sproutSeedBtn && sproutSeedBtn.getAttribute('data-state') === 'on') {
            sproutSeedBtn.setAttribute('data-state', 'off');
            manualSeed.disabled = false;
        }

        // Update placeholder to show the seed value if available, or "Random" if not
        if (window.lastLoadedSeed) {
            manualSeed.placeholder = window.lastLoadedSeed || 'Randomize';
        } else {
            manualSeed.placeholder = 'Randomize';
        }
    }
    manualSeed.dispatchEvent(new Event('input', { bubbles: true }));
}

function updateSproutSeedButton() {
    if (sproutSeedBtn) {
        if (window.lastLoadedSeed) {
            sproutSeedBtn.classList.remove('hidden');
            // Update placeholder to show the seed value
            if (manualSeed) {
                manualSeed.placeholder = window.lastLoadedSeed || 'Randomize';
            }
        } else {
            sproutSeedBtn.classList.add('hidden');
            // Reset toggle state when no seed is available
            sproutSeedBtn.setAttribute('data-state', 'off');
            // Update placeholder to show "Random"
            if (manualSeed) {
                manualSeed.placeholder = 'Randomize';
            }
        }
    }
}

function updateSproutSeedButtonFromPreviewSeed() {
    if (sproutSeedBtn) {
        const seedValue = window.lastGeneratedSeed || window.lastLoadedSeed;
        if (seedValue !== null && seedValue !== undefined) {
            // Enable the sprout seed button and show it
            sproutSeedBtn.classList.remove('hidden');
            // Set the lastLoadedSeed so the button can function
            window.lastLoadedSeed = seedValue;

            if (manualSeed) {
                manualSeed.placeholder = seedValue.toString() || 'Randomize';
            }

            // Check if the button is currently in 'on' state
            const currentState = sproutSeedBtn.getAttribute('data-state');
            if (currentState === 'on') {
                // If randomize seed is off, check if current input value matches preview seed
                const currentInputValue = manualSeed ? parseInt(manualSeed.value) || '' : '';

                if (currentInputValue !== seedValue) {
                    loadSeedBtn.classList.remove('hidden');
                } else {
                    loadSeedBtn.classList.add('hidden');
                }
                // Don't auto-update the input field when there's a mismatch
            } else {
                // Reset button state to off initially and hide load seed button
                sproutSeedBtn.setAttribute('data-state', 'off');
                loadSeedBtn.classList.add('hidden');
            }
        } else {
            // Hide the buttons when no seed is available
            sproutSeedBtn.classList.add('hidden');
            sproutSeedBtn.setAttribute('data-state', 'off');
            loadSeedBtn.classList.add('hidden');
            // Clear the lastLoadedSeed
            window.lastLoadedSeed = null;

            // Update placeholder to show "Random"
            if (manualSeed) {
                manualSeed.placeholder = 'Randomize';
            }
        }
    }
}

function loadSeedFromPreview() {
    if (!loadSeedBtn || !window.lastGeneratedSeed) return;

    // Load the seed from the preview into the manual seed input
    if (manualSeed) {
        manualSeed.value = window.lastGeneratedSeed.toString();
        manualSeed.disabled = false; // Keep the field enabled for editing
    }

    // Hide the load seed button since the seed has been loaded
    loadSeedBtn.classList.add('hidden');

    // Set the sprout seed button to "on" state (unlocked) since we loaded a specific seed
    if (sproutSeedBtn) {
        sproutSeedBtn.setAttribute('data-state', 'on');
    }

    // Update the sprout seed button to reflect the new state
    updateSproutSeedButtonFromPreviewSeed();
    manualSeed.dispatchEvent(new Event('input', { bubbles: true }));
}

/** Genso seeds present (whether or not they're already locked). */
function sproutHasGensoSeedList() {
    return Array.isArray(window.lastGenerationTextReplacements) && window.lastGenerationTextReplacements.length > 0;
}


/** At least one lockable expander is still unlocked — "Text Expanders +" still does something. */
function sproutNeedsExpandersLockChoice() {
    const seeds = window.lastGenerationTextReplacements;
    if (!Array.isArray(seeds) || seeds.length === 0) return false;
    const lockable = seeds.filter(r => (r.can_lock !== undefined ? r.can_lock !== false : true));
    if (lockable.length === 0) return false;
    return lockable.some(r => r.locked !== true);
}

function loadSproutExpandersFromPreviewMetadata() {
    if (!window.currentManualPreviewImage || !window.currentManualPreviewImage.metadata) return;
    const metadata = window.currentManualPreviewImage.metadata;
    if (!metadata.text_replacements_seed || !Array.isArray(metadata.text_replacements_seed)) return;

    const replacementsWithLockStatus = metadata.text_replacements_seed
        .filter(r => r.can_lock !== undefined ? r.can_lock !== false : true)
        .map(replacement => ({
            ...replacement,
            locked: true
        }));

    window.lastGenerationTextReplacements = replacementsWithLockStatus;
    window.lockedTextReplacements = replacementsWithLockStatus;
    updateMainLockButtonState();
}

function applySproutExpandersLockFromMemoryOrMetadata() {
    if (window.lastGenerationTextReplacements && window.lastGenerationTextReplacements.length > 0) {
        window.lastGenerationTextReplacements = window.lastGenerationTextReplacements.map(r => ({
            ...r,
            locked: (r.can_lock !== undefined ? r.can_lock !== false : true)
        }));
        window.lockedTextReplacements = window.lastGenerationTextReplacements.filter(s => s.locked);
        updateMainLockButtonState();
        return;
    }
    loadSproutExpandersFromPreviewMetadata();
}

async function toggleSproutSeed() {
    if (!sproutSeedBtn || !window.lastLoadedSeed) return;

    const currentState = sproutSeedBtn.getAttribute('data-state');
    const turningOff = currentState === 'on';

    if (turningOff) {
        sproutSeedBtn.setAttribute('data-state', 'off');
        manualSeed.value = '';
        manualSeed.disabled = false;
        if (manualSeed) {
            manualSeed.placeholder = window.lastLoadedSeed || 'Randomize';
        }
        manualSeed.dispatchEvent(new Event('input', { bubbles: true }));
        return;
    }

    const wantsExpanders = sproutNeedsExpandersLockChoice();
    const wantsTendai = dynamicGenerationNeedsTendaiLockChoice();
    /** No extra pinning exists beyond the seed → lock seed without a dialog */
    let scope = 'seed';
    if (wantsExpanders || wantsTendai) {
        const dialogButtons = [];
        if (wantsTendai) {
            dialogButtons.push({ text: 'Tendai +', value: 'tendai', className: 'btn-secondary' });
        }
        if (wantsExpanders) {
            dialogButtons.push({ text: 'Text Expanders +', value: 'expanders', className: 'btn-secondary' });
        }
        dialogButtons.push({ text: 'Seed', value: 'seed', className: 'btn-secondary' });
        const maxIdx = dialogButtons.findIndex(b => b.value === 'tendai');
        const primaryIdx = maxIdx !== -1 ? maxIdx : dialogButtons.findIndex(b => b.value === 'expanders');
        const pinIdx = primaryIdx !== -1 ? primaryIdx : dialogButtons.length - 1;
        dialogButtons.forEach((b, i) => {
            if (i === pinIdx) {
                b.className = 'btn-primary';
                b.primary = true;
            }
        });

        let msgParts = [];
        if (wantsTendai && wantsExpanders) {
            msgParts.push('Pinned Tendai output and unlocked Genso expanders are mixed with this seed.');
        } else if (wantsTendai) {
            msgParts.push('A cached Tendai compile can still be pinned.');
        } else {
            msgParts.push('Genso expanders can still be fully locked.');
        }
        msgParts.push('Pick what to pin with this seed.');
        const choice = await showConfirmationDialog(
            msgParts.join(' '),
            dialogButtons,
            null,
            { title: 'Lock seed scope', icon: 'fas fa-dice' }
        );
        if (choice === null || choice === undefined) return;
        scope = choice;
    }

    sproutSeedBtn.setAttribute('data-state', 'on');
    manualSeed.value = window.lastLoadedSeed;
    if (window.lastLoadedSeed) {
        sproutSeedBtn?.classList.remove('hidden');
    }

    manualSeed.disabled = true;
    if (manualSeed) {
        manualSeed.placeholder = window.lastLoadedSeed || 'Randomize';
    }

    if (scope === 'seed') {
        // Seed only — keep in-memory Genso locks. If there is no list yet, match older behavior: pull from preview metadata when nothing else is in play.
        if (!sproutHasGensoSeedList() && !dynamicGenerationHasCompileCache()) {
            loadSproutExpandersFromPreviewMetadata();
        }
    } else if (scope === 'expanders') {
        applySproutExpandersLockFromMemoryOrMetadata();
    } else if (scope === 'tendai') {
        if (sproutNeedsExpandersLockChoice()) {
            applySproutExpandersLockFromMemoryOrMetadata();
        }
        setDynamicGenerationLockState({ cacheLocked: true, contextLocked: true });
    }

    manualSeed.dispatchEvent(new Event('input', { bubbles: true }));
}

// Add event listener for manualSampler to auto-set noise scheduler
async function fetchWithAuth(url, options = {}) {
    if (!(await ensureSessionValid())) {
        handleAuthError(new Error('Unauthorized access'), 'fetchWithAuth');
        return Promise.reject(new Error('Session invalid or cancelled'));
    }
    return fetch(url, options);
};

// Handle image upload from file input
async function handleImageUpload(event) {
    const files = Array.from(event.target.files);
    if (files.length === 0) return;

    // Filter for image files
    const imageFiles = files.filter(file => file.type.startsWith('image/'));
    const nonImageFiles = files.filter(file => !file.type.startsWith('image/'));

    if (nonImageFiles.length > 0) {
        showGlassToast('warning', 'Invalid Files', `${nonImageFiles.length} non-image files were skipped`, false, undefined, '<i class="fas fa-file-circle-question"></i>');
    }

    if (imageFiles.length === 0) {
        showGlassToast('error', 'No Images', 'Please select image files only', false, undefined, '<i class="fas fa-file-circle-xmark"></i>');
        return;
    }

    await uploadImages(imageFiles);

    // Clear the input so the same files can be selected again
    event.target.value = '';
}

// Handle clipboard paste
async function handleClipboardBlueprintText(text) {
    try {
        const data = JSON.parse(text);
        const isNovelAI = data && (
            (data.source && data.source.includes('NovelAI')) ||
            data.v4_prompt ||
            data.signed_hash ||
            data.request_type === 'PromptGenerateRequest' ||
            data.request_type === 'Img2ImgRequest'
        );

        if (!isNovelAI) {
            console.log('Clipboard text is not a NovelAI blueprint');
            return;
        }

        const toastId = showGlassToast('info', 'Loading Blueprint', 'Loading blueprint from clipboard...', true, false, '<i class="nai-import"></i>');

        try {
            if (!data.source) {
                data.source = 'NovelAI';
            }

            const transformedMetadata = window.transformMetadataForEditor(data);
            await openManualModalWithContent({
                type: 'metadata',
                data: transformedMetadata
            });

            updateGlassToastComplete(toastId, {
                type: 'success',
                title: 'Blueprint Loaded',
                message: 'Successfully loaded blueprint from clipboard',
                customIcon: '<i class="nai-check"></i>',
                showProgress: false
            });
        } catch (error) {
            console.error('Error loading blueprint:', error);
            updateGlassToastComplete(toastId, {
                type: 'error',
                title: 'Blueprint Load Failed',
                message: 'Failed to load blueprint: ' + error.message,
                customIcon: '<i class="nai-cross"></i>',
                showProgress: false
            });
        }
    } catch (e) {
        console.log('Clipboard text is not valid JSON');
    }
}

async function handleClipboardPaste(event) {
    // Check if user is typing in an input field - don't intercept paste in that case
    const activeElement = document.activeElement;
    const isTypingInField = activeElement && (
        activeElement.tagName === 'INPUT' ||
        activeElement.tagName === 'TEXTAREA' ||
        activeElement.isContentEditable
    );

    // If user is typing, let the default paste behavior happen
    if (isTypingInField) {
        return;
    }

    const clipboardItems = event.clipboardData?.items;
    if ((!clipboardItems || clipboardItems.length === 0) && isAndroidClipboardBridgeActive()) {
        event.preventDefault();
        try {
            const result = await readClipboard();
            if (result.empty) return;

            const imageFile = getPrimaryImageFileFromClipboardResult(result);
            if (imageFile) {
                await uploadImages([imageFile]);
                return;
            }

            const text = getPrimaryTextFromClipboardResult(result);
            if (text) {
                await handleClipboardBlueprintText(text);
            }
        } catch (error) {
            console.warn('📱 Android clipboard paste failed:', error);
        }
        return;
    }

    if (!clipboardItems) return;

    // First check for text/JSON data (blueprint)
    for (let item of clipboardItems) {
        if (item.type === 'text/plain') {
            event.preventDefault();
            item.getAsString(async (text) => {
                await handleClipboardBlueprintText(text);
            });
            return;
        }
    }

    // If no text data found, check for images
    for (let item of clipboardItems) {
        if (item.type.startsWith('image/')) {
            event.preventDefault();
            const file = item.getAsFile();
            if (file) {
                await uploadImages([file]);
            }
            break;
        }
    }
}

let showSubscriptionExpirationToast = false;
let showFixedTrainingStepsToast = false;

function isDesktopTrayBootPending() {
    return !!(window.isDesktop && !window._systemTrayBootComplete);
}
window.isDesktopTrayBootPending = isDesktopTrayBootPending;

function isSystemTrayBootComplete() {
    return !window.isDesktop || window._systemTrayBootComplete === true;
}

function shouldDeferTrayNotifications() {
    return isDesktopTrayBootPending();
}

function revealTrayIconElement(el, animate = true) {
    if (!el) return;
    el.classList.remove('hidden');
    if (animate) {
        el.classList.remove('tray-boot-in');
        void el.offsetWidth;
        el.classList.add('tray-boot-in');
    }
}

function revealTrayIconById(id, animate = true) {
    revealTrayIconElement(document.getElementById(id), animate);
}

async function checkSubscriptionExpiration(options = {}) {
    if (!window.optionsData?.user?.subscription?.expiresAt) return;

    const renewalData = getSubscriptionRenewalDisplayData(window.optionsData.user.subscription.expiresAt);
    const subTier = window.optionsData.user.subscription.tier;
    const subName = subTier === 3 ? 'Opus' : subTier === 2 ? 'Scroll' : subTier === 1 ? 'Tablet' : 'Enterprise';

    if (renewalData.msUntilRenewal <= (7 * 24 * 60 * 60 * 1000) && renewalData.msUntilRenewal > 0) {
        if (!options.forceDisplay && shouldDeferTrayNotifications()) {
            return;
        }
        if (!showSubscriptionExpirationToast) {
            const message = `Your NovelAI ${subName} subscription will renew in ${renewalData.timeRemaining}! (${renewalData.renewalDateTimeStr})`;
            showGlassToast('warning', 'NovelAI Subscription Status', message, false, 15000);
            showSubscriptionExpirationToast = true;
        }
    }
}

async function checkFixedTrainingSteps(options = {}) {
    if (!window.optionsData?.balance || !window.optionsData?.user?.subscription?.expiresAt) {
        console.error('No balance data available');
        return;
    }

    const fixedSteps = window.optionsData.balance.fixedTrainingStepsLeft || 0;
    const renewalData = getSubscriptionRenewalDisplayData(window.optionsData.user.subscription.expiresAt);
    const daysUntilRenewal = Math.max(1, renewalData.daysUntilRenewal);
    const usePerDay = parseInt((fixedSteps / daysUntilRenewal).toFixed(0));
    const usePerHour = Math.max(1, parseInt((fixedSteps / Math.max(1, renewalData.hoursUntilRenewal)).toFixed(0)));
    const pacingSuggestion = renewalData.hoursUntilRenewal < 96
        ? `${usePerHour} Anlas per hour`
        : `${usePerDay} Anlas per day`;
    if (fixedSteps > 500 && daysUntilRenewal <= 15 && daysUntilRenewal > 0) {
        if (!options.forceDisplay && shouldDeferTrayNotifications()) {
            return;
        }
        if (!showFixedTrainingStepsToast) {
            showGlassToast('info', 'Account Fixed Anlas Expiring',
                `You have <i class="nai-anla"></i> ${fixedSteps} Fixed Anlas remaining that will expire.<br/>
                Consider burning <i class="nai-anla"></i> ${pacingSuggestion} over the next ${renewalData.timeRemaining}.`, false, 300000, '<i class="nai-anla"></i>');
            showFixedTrainingStepsToast = true;
        }
    } else {
        // Reset so the toast can fire again when account state re-enters the warning window.
        showFixedTrainingStepsToast = false;
    }
}

async function flushDeferredAccountTrayNotifications() {
    await checkSubscriptionExpiration({ forceDisplay: true });
    await checkFixedTrainingSteps({ forceDisplay: true });
}

function flushDeferredNetworkTrayNotifications() {
    if (!window.wsClient || typeof window.wsClient.flushDeferredPingTrayNotification !== 'function') return;
    window.wsClient.flushDeferredPingTrayNotification();
}

function getSubscriptionRenewalDisplayData(expiresAtUnix) {
    const expiresAt = new Date(expiresAtUnix * 1000);
    const now = new Date();
    const msUntilRenewal = expiresAt - now;
    const hourMs = 1000 * 60 * 60;
    const dayMs = 1000 * 60 * 60 * 24;

    // Use ceiling so users are warned before a period fully elapses.
    const hoursUntilRenewal = Math.ceil(msUntilRenewal / hourMs);
    const daysUntilRenewal = Math.ceil(msUntilRenewal / dayMs);

    // Calendar-day delta in local timezone avoids "2 days" when renewal date is tomorrow locally.
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const startOfRenewalDay = new Date(expiresAt.getFullYear(), expiresAt.getMonth(), expiresAt.getDate());
    const calendarDaysUntilRenewal = Math.max(0, Math.round((startOfRenewalDay - startOfToday) / dayMs));

    const useHours = hoursUntilRenewal < 96;
    const timeRemainingValue = useHours ? hoursUntilRenewal : calendarDaysUntilRenewal;
    const timeRemainingUnit = useHours ? 'hour' : 'day';
    const timeRemaining = `${timeRemainingValue} ${timeRemainingUnit}${timeRemainingValue !== 1 ? 's' : ''}`;
    const renewalDateTimeStr = expiresAt.toLocaleString(undefined, {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
        timeZoneName: 'short'
    });

    return {
        msUntilRenewal,
        hoursUntilRenewal,
        daysUntilRenewal,
        calendarDaysUntilRenewal,
        timeRemaining,
        renewalDateTimeStr
    };
}

async function updateSubscriptionNotifications() {
    await checkSubscriptionExpiration();
    await checkFixedTrainingSteps();

    // Update subscription renewal indicator
    updateSubscriptionRenewalIndicator();
}

// System Tray Icons Management
const SYSTEM_TRAY_BOOT_STAGGER_MS = 70;

function prepareSystemTrayBackground() {
    if (window._systemTrayBackgroundPrepared) return;
    window._systemTrayBackgroundPrepared = true;

    const trayIconIds = [
        'imageGenerationIndicator',
        'subscriptionRenewalIndicator',
        'fixedCreditsIndicator',
        'searchIndexingIndicator',
        'desktopSaveTrayIndicator',
        'generationQuipsTrayIcon',
        'naxtBagTrayIcon',
        'phasewalkerTrayIcon',
        'workspaceTrayIcon',
        'serviceWorkerTrayIcon',
        'pingWarningIndicator',
        'modemTrayIcon'
    ];

    trayIconIds.forEach((id) => {
        const el = document.getElementById(id);
        if (el) el.classList.add('hidden');
    });

    setInterval(updateSubscriptionRenewalIndicator, 3600000);
    setInterval(updateFixedCreditsIndicator, 60000);
    setInterval(updateImageGenerationIndicator, 500);
}

async function startBackgroundTrayServices() {
    if (!window.isDesktop) return;

    updateFixedCreditsIndicator({ reveal: false });
    updateSubscriptionRenewalIndicator({ reveal: false });
    updateWorkspaceTrayIcon({ reveal: false });
    updateSearchIndexingIndicator();
    setupServiceWorkerTrayContextMenu();
    // initializeGenerationQuipsTray: public/scripts/comp/generationQuipsTray.js
    if (typeof initializeGenerationQuipsTray === 'function') {
        initializeGenerationQuipsTray();
    }
    // initializeNaxtBagTray: public/scripts/comp/naxtApplet.js
    if (typeof initializeNaxtBagTray === 'function') {
        initializeNaxtBagTray();
    }
    // initializePhasewalkerTray: public/scripts/comp/bracketGenerationApplet.js
    if (typeof initializePhasewalkerTray === 'function') {
        initializePhasewalkerTray();
    }
    updateImageGenerationIndicator({ reveal: false });

    if (window.wsClient) {
        if (typeof window.wsClient._updateServiceWorkerTrayIcon === 'function') {
            window.wsClient._updateServiceWorkerTrayIcon();
        }
        if (typeof window.wsClient._updateModemTrayIcon === 'function') {
            window.wsClient._updateModemTrayIcon();
        }
        if (typeof window.wsClient.updatePingWarningIcon === 'function') {
            window.wsClient.updatePingWarningIcon({ reveal: false });
        }
    }

    window._systemTrayBootComplete = true;

    const revealPlan = [
        () => {
            updateFixedCreditsIndicator({ reveal: true });
            return 'fixedCreditsIndicator';
        },
        () => {
            updateSubscriptionRenewalIndicator({ reveal: true });
            return 'subscriptionRenewalIndicator';
        },
        () => {
            updateWorkspaceTrayIcon({ reveal: true });
            return 'workspaceTrayIcon';
        },
        () => {
            revealTrayIconById('searchIndexingIndicator');
            return 'searchIndexingIndicator';
        },
        () => {
            revealTrayIconById('serviceWorkerTrayIcon');
            return 'serviceWorkerTrayIcon';
        },
        () => {
            revealTrayIconById('modemTrayIcon');
            return 'modemTrayIcon';
        },
        () => {
            if (window.naxtApplet && typeof window.naxtApplet.updateBagTrayChrome === 'function') {
                window.naxtApplet.updateBagTrayChrome();
            }
            return 'naxtBagTrayIcon';
        },
        () => {
            if (window.bracketGenerationApplet && typeof window.bracketGenerationApplet.updateTrayChrome === 'function') {
                window.bracketGenerationApplet.updateTrayChrome();
            }
            return 'phasewalkerTrayIcon';
        },
        () => {
            if (window.wsClient && typeof window.wsClient.updatePingWarningIcon === 'function') {
                window.wsClient.updatePingWarningIcon({ reveal: true });
            }
            return 'pingWarningIndicator';
        },
        () => {
            updateImageGenerationIndicator({ reveal: true });
            return 'imageGenerationIndicator';
        }
    ];

    let delay = 0;
    revealPlan.forEach((revealFn) => {
        setTimeout(() => {
            const id = revealFn();
            const el = document.getElementById(id);
            if (el && !el.classList.contains('hidden')) {
                revealTrayIconElement(el);
            }
        }, delay);
        delay += SYSTEM_TRAY_BOOT_STAGGER_MS;
    });

    setTimeout(async () => {
        await flushDeferredAccountTrayNotifications();
        flushDeferredNetworkTrayNotifications();
    }, delay + SYSTEM_TRAY_BOOT_STAGGER_MS);
}


function setupTrayIconPopovers() {
    if (!window.PopoverManager) return;

    const trayIcons = [
        'subscriptionRenewalIndicator',
        'fixedCreditsIndicator',
        'imageGenerationIndicator',
        'searchIndexingIndicator',
        'workspaceTrayIcon',
        'serviceWorkerTrayIcon',
        'modemTrayIcon',
        'pingWarningIndicator',
        'taskbarWebsocketIndicator'
    ];

    trayIcons.forEach(iconId => {
        const icon = document.getElementById(iconId);
        if (!icon) return;

        // Attach popover with hover-only mode
        window.PopoverManager.attach(icon, {
            content: icon.title || '',
            hoverOnly: true,
            position: 'top',
            arrowPosition: 'bottom-right',
            onShow: (popover, element) => {
                // Update content from title attribute
                const title = element.title || '';
                if (title) {
                    window.PopoverManager.updateContent(element, title);
                }
            }
        });

        // Watch for title changes and update popover
        const observer = new MutationObserver(() => {
            if (icon.title) {
                window.PopoverManager.updateContent(icon, icon.title);
            }
        });

        observer.observe(icon, {
            attributes: true,
            attributeFilter: ['title']
        });
    });
}


// Track active popover timers
let activePopoverTimer = null;
let popoverInteractionListeners = null;

/**
 * Start the auto-hide timer for the popover, but only when window is focused and user has interacted
 * @param {HTMLElement} indicator - The indicator element
 */
function startPopoverAutoHideTimer(indicator) {
    // Clear any existing timer
    if (activePopoverTimer) {
        clearTimeout(activePopoverTimer);
        activePopoverTimer = null;
    }

    // Remove any existing interaction listeners
    if (popoverInteractionListeners) {
        popoverInteractionListeners.cleanup();
        popoverInteractionListeners = null;
    }

    // Check if window is currently in focus
    const isFocused = document.hasFocus() && !document.hidden;
    let hasInteracted = false;

    // Function to start the timer
    const startTimer = () => {
        if (activePopoverTimer) {
            clearTimeout(activePopoverTimer);
        }

        activePopoverTimer = setTimeout(() => {
            if (PopoverManager) {
                PopoverManager.hide(indicator);
            }
            activePopoverTimer = null;

            // Clean up listeners
            if (popoverInteractionListeners) {
                popoverInteractionListeners.cleanup();
                popoverInteractionListeners = null;
            }
        }, 15000);
    };

    // If already focused, set up interaction listeners
    if (isFocused) {
        const onMouseMove = () => {
            hasInteracted = true;
            startTimer();
            cleanupListeners();
        };

        const onTouchStart = () => {
            hasInteracted = true;
            startTimer();
            cleanupListeners();
        };

        const onFocus = () => {
            if (hasInteracted) {
                startTimer();
            }
        };

        const onVisibilityChange = () => {
            if (!document.hidden && hasInteracted) {
                startTimer();
            } else if (document.hidden) {
                // Pause timer if window loses focus
                if (activePopoverTimer) {
                    clearTimeout(activePopoverTimer);
                    activePopoverTimer = null;
                }
            }
        };

        const cleanupListeners = () => {
            document.removeEventListener('mousemove', onMouseMove, { passive: true });
            document.removeEventListener('touchstart', onTouchStart, { passive: true });
            window.removeEventListener('focus', onFocus);
            document.removeEventListener('visibilitychange', onVisibilityChange);
        };

        // Store cleanup function
        popoverInteractionListeners = {
            cleanup: cleanupListeners
        };

        // Listen for mouse movement or touch
        document.addEventListener('mousemove', onMouseMove, { passive: true, once: true });
        document.addEventListener('touchstart', onTouchStart, { passive: true, once: true });

        // Also listen for window focus/visibility changes
        window.addEventListener('focus', onFocus);
        document.addEventListener('visibilitychange', onVisibilityChange);
    } else {
        // Window not focused - wait for focus and interaction
        const onFocus = () => {
            // Set up interaction listeners when window gains focus
            const onMouseMove = () => {
                hasInteracted = true;
                startTimer();
                cleanupListeners();
            };

            const onTouchStart = () => {
                hasInteracted = true;
                startTimer();
                cleanupListeners();
            };

            const onVisibilityChange = () => {
                if (document.hidden) {
                    // Pause timer if window loses focus
                    if (activePopoverTimer) {
                        clearTimeout(activePopoverTimer);
                        activePopoverTimer = null;
                    }
                } else if (hasInteracted) {
                    startTimer();
                }
            };

            const cleanupListeners = () => {
                document.removeEventListener('mousemove', onMouseMove, { passive: true });
                document.removeEventListener('touchstart', onTouchStart, { passive: true });
                window.removeEventListener('focus', onFocus);
                document.removeEventListener('visibilitychange', onVisibilityChange);
            };

            // Store cleanup function
            popoverInteractionListeners = {
                cleanup: cleanupListeners
            };

            // Listen for mouse movement or touch
            document.addEventListener('mousemove', onMouseMove, { passive: true, once: true });
            document.addEventListener('touchstart', onTouchStart, { passive: true, once: true });
            document.addEventListener('visibilitychange', onVisibilityChange);

            window.removeEventListener('focus', onFocus);
        };

        window.addEventListener('focus', onFocus);

        // Also listen for visibility changes
        const onVisibilityChange = () => {
            if (!document.hidden) {
                onFocus();
            }
        };

        document.addEventListener('visibilitychange', onVisibilityChange);

        // Store cleanup function
        popoverInteractionListeners = {
            cleanup: () => {
                window.removeEventListener('focus', onFocus);
                document.removeEventListener('visibilitychange', onVisibilityChange);
            }
        };
    }
}

